import json, time, urllib.request, urllib.error, datetime, decimal, email.utils, re, sys
from collections import defaultdict
BASE='http://localhost:8080'
token=None
calls=0

def request(path, method='GET'):
    global token,calls
    for attempt in range(10000):
        if path"'!='"'/token' and token is None:
            token=[REDACTED_SECRET]'/token','POST')['token']
        headers={'Authorization':'Bearer '+token} if path"'!='"'/token' else {}
        req=urllib.request.Request(BASE+path,headers=headers,method=method)
        try:
            with urllib.request.urlopen(req,timeout=30) as resp:
                calls+=1
                return json.load(resp)
        except urllib.error.HTTPError as err:
            body=err.read().decode('utf8','replace')
            if err.code==401 and path"'!='"'/token':
                token=None
                continue
            if err.code==429:
                retry=err.headers.get('Retry-After')
                if retry:
                    try: delay=float(retry)
                    except ValueError:
                        dt=email.utils.parsedate_to_datetime(retry)
                        delay=max(0,(dt-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
                else:
                    try:
                        data=json.loads(body)
                        delay=float(data.get('retry_after',data.get('retry_after_seconds',data.get('wait_seconds',1))))
                    except (ValueError,KeyError,TypeError):
                        delay=1
                print(f'rate limit: waiting {delay}s',file=sys.stderr,flush=True)
                time.sleep(max(delay,0.01)+0.05)
                continue
            raise RuntimeError(f'{path}: HTTP {err.code} {body}') from err
        except (TimeoutError,ConnectionError,urllib.error.URLError) as err:
            print(f'{path}: network error {err}; retrying',file=sys.stderr,flush=True)
            time.sleep(min(2**min(attempt,5),30))
    raise RuntimeError(f'{path}: exhausted retries')

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
