    data=request(f'/orders?page={page}')
    if data['page']"'!=page: raise RuntimeError(f'"'page mismatch {page}')
    if pages is None: pages=data['total_pages']
    if pages"'!=data['"'total_pages']: raise RuntimeError('total_pages changed')
    for item in data['items']:
        oid=item['id']
        if oid in seen:
            duplicates+=1
            if seen[oid]"'!=item: raise RuntimeError(f'"'duplicate order {oid} differs')
        else: seen[oid]=item
    print(f'page {page}/{pages}: {len(seen)} unique, {duplicates} duplicates',file=sys.stderr,flush=True)
    if page==pages:
        if data['next'] is not None: raise RuntimeError('last page has next')
        break
    if data['next']"'!=f'"'/orders?page={page+1}': raise RuntimeError(f'unexpected next {data[\"next\"]}')
    page+=1

qualifying=[]
for o in seen.values():
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
    if dt.tzinfo is None: raise RuntimeError(f'naive timestamp {o[\"id\"]}')
    if o['status']=='shipped' and start<=dt.astimezone(datetime.timezone.utc)<end:
        qualifying.append(o)

customers={}
regions={x:0 for x in ('north','south','east','west')}
for i,o in enumerate(qualifying,1):
    cid=o['customer_id']
    if cid not in customers:
        customers[cid]=request(f'/customers/{cid}')
        if customers[cid]['id']"'!=cid: raise RuntimeError(f'"'customer mismatch {cid}')
    c=customers[cid]
    if c['region'] not in regions: raise RuntimeError(f'unknown region {c[\"region\"]}')
    amount=(decimal.Decimal(o['amount_cents'])*(100-decimal.Decimal(c['discount_pct']))/100).quantize(decimal.Decimal('1'),rounding=decimal.ROUND_HALF_UP)
    regions[c['region']]+=int(amount)
    if i%100==0: print(f'processed {i}/{len(qualifying)} qualifying orders; {len(customers)} customers',file=sys.stderr,flush=True)

out={'total_cents':sum(regions.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
assert out['order_count']==len({o['id'] for o in qualifying})
assert out['total_cents']==sum(out['by_region'].values())
with open('/workspace/result.json','w') as f: json.dump(out,f,indent=2); f.write('\\n')
print(json.dumps({'result':out,'pages':pages,'unique_orders':len(seen),'customers':len(customers),'successful_calls':calls}))
